import Foundation

protocol DownloadDelegate: AnyObject {
    func downloadDidFinish(bytes: Int)
}

final class Downloader {
    weak var delegate: DownloadDelegate?
    func run() {
        delegate?.downloadDidFinish(bytes: 1024)
    }
}

final class Tracker: DownloadDelegate {
    func downloadDidFinish(bytes: Int) {
        print("Received \(bytes) bytes")
    }
}

let d = Downloader()
let t = Tracker()
d.delegate = t
d.run()

import Foundation

final class Worker {
    var onComplete: (() -> Void)?
    func start() {
        onComplete?()
    }
}

final class Manager {
    var name = "Team Alpha"
    let worker = Worker()

    func setup() {
        worker.onComplete = { [weak self] in
            if let self {
                print("Finished for \(self.name)")
            }
        }
    }
}

let m = Manager()
m.setup()
m.worker.start()

