import Foundation

extension Notification.Name {
    static let itemPurchased = Notification.Name("itemPurchased")
}

final class PurchaseNotifier {
    private var token: NSObjectProtocol?

    func listen() {
        token = NotificationCenter.default.addObserver(
            forName: .itemPurchased,
            object: nil,
            queue: nil
        ) { note in
            if let item = note.userInfo?["item"] as? String {
                print("Purchased \(item)")
            }
        }
    }

    func postPurchase(item: String) {
        NotificationCenter.default.post(
            name: .itemPurchased,
            object: nil,
            userInfo: ["item": item]
        )
    }

    func stop() {
        if let token = token {
            NotificationCenter.default.removeObserver(token)
            self.token = nil
        }
    }
}

let notifier = PurchaseNotifier()
notifier.listen()
notifier.postPurchase(item: "Coffee")
notifier.stop()
